package EmployeeManagementSystem.service;
import EmployeeManagementSystem.dto.EmployeeDocumentDTO; import EmployeeManagementSystem.entity.EmployeeDocument; import EmployeeManagementSystem.repository.EmployeeDocumentRepository; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile;
import java.io.*; import java.nio.file.*; import java.time.*; import java.util.*;
@Service public class EmployeeDocumentService {
 private final EmployeeDocumentRepository repo; private final Path root;
 public EmployeeDocumentService(EmployeeDocumentRepository repo,@Value("${app.upload.dir:uploads/employee-documents}") String dir){this.repo=repo;root=Paths.get(dir).toAbsolutePath().normalize();try{Files.createDirectories(root);}catch(IOException e){throw new IllegalStateException("Unable to create document storage",e);}}
 public List<EmployeeDocumentDTO> list(String employeeId,boolean all){List<EmployeeDocument> x=all?repo.findAllByOrderByUploadedAtDesc():repo.findByEmployeeIdOrderByUploadedAtDesc(employeeId);return x.stream().map(this::dto).toList();}
 public EmployeeDocumentDTO upload(String employeeId,String employeeName,String actor,MultipartFile file,String category,LocalDate issue,LocalDate expiry,String desc)throws IOException{
  if(file==null||file.isEmpty())throw new IllegalArgumentException("Please select a file."); if(file.getSize()>10*1024*1024)throw new IllegalArgumentException("Maximum file size is 10 MB.");
  String original=Optional.ofNullable(file.getOriginalFilename()).orElse("document"); String lower=original.toLowerCase(Locale.ROOT); List<String> allowed=List.of(".pdf",".jpg",".jpeg",".png",".doc",".docx"); if(allowed.stream().noneMatch(lower::endsWith))throw new IllegalArgumentException("Allowed file types: PDF, JPG, PNG, DOC, DOCX.");
  original=Optional.ofNullable(file.getOriginalFilename()).orElse("document"); String ext="";int p=original.lastIndexOf('.');if(p>=0)ext=original.substring(p).replaceAll("[^A-Za-z0-9.]",""); String stored=UUID.randomUUID()+ext; Path target=root.resolve(stored).normalize();if(!target.startsWith(root))throw new IllegalArgumentException("Invalid filename"); Files.copy(file.getInputStream(),target,StandardCopyOption.REPLACE_EXISTING);
  EmployeeDocument d=EmployeeDocument.builder().employeeId(employeeId).employeeName(employeeName).category(category==null||category.isBlank()?"OTHER":category).originalFilename(original).storedFilename(stored).contentType(file.getContentType()).fileSize(file.getSize()).status("PENDING").issueDate(issue).expiryDate(expiry).description(desc).uploadedBy(actor).build();return dto(repo.save(d));
 }
 public EmployeeDocument getOwned(Long id,String userId,boolean admin){return admin?repo.findById(id).orElseThrow(()->new NoSuchElementException("Document not found.")):repo.findByIdAndEmployeeId(id,userId).orElseThrow(()->new NoSuchElementException("Document not found."));}
 public byte[] bytes(EmployeeDocument d)throws IOException{return Files.readAllBytes(storedPath(d.getStoredFilename()));}
 public void delete(Long id,String userId,boolean admin){EmployeeDocument d=getOwned(id,userId,admin);Path storedPath=storedPath(d.getStoredFilename());if(!admin&&!List.of("PENDING","REJECTED").contains(d.getStatus()))throw new IllegalStateException("Only pending or rejected documents can be deleted.");repo.delete(d);try{Files.deleteIfExists(storedPath);}catch(IOException ignored){}}
 private Path storedPath(String filename){if(filename==null||filename.isBlank())throw new IllegalArgumentException("Invalid stored document filename.");Path path=root.resolve(filename).normalize();if(path.equals(root)||!path.startsWith(root))throw new IllegalArgumentException("Invalid stored document filename.");return path;}
 public EmployeeDocumentDTO review(Long id,String actor,String status,String comment){EmployeeDocument d=repo.findById(id).orElseThrow(()->new NoSuchElementException("Document not found."));if(!List.of("VERIFIED","REJECTED").contains(status))throw new IllegalArgumentException("Invalid review status.");d.setStatus(status);d.setVerifiedBy(actor);d.setVerifiedAt(LocalDateTime.now());d.setReviewComment(comment);return dto(repo.save(d));}
 private EmployeeDocumentDTO dto(EmployeeDocument d){LocalDate today=LocalDate.now();boolean expired=d.getExpiryDate()!=null&&d.getExpiryDate().isBefore(today);boolean soon=d.getExpiryDate()!=null&&!expired&&!d.getExpiryDate().isAfter(today.plusDays(30));if(expired&&!"REJECTED".equals(d.getStatus())&&!"EXPIRED".equals(d.getStatus())){d.setStatus("EXPIRED");repo.save(d);}return new EmployeeDocumentDTO(d.getId(),d.getEmployeeId(),d.getEmployeeName(),d.getCategory(),d.getOriginalFilename(),d.getContentType(),d.getFileSize(),d.getStatus(),d.getIssueDate(),d.getExpiryDate(),d.getDescription(),d.getUploadedBy(),d.getUploadedAt(),d.getVerifiedBy(),d.getVerifiedAt(),d.getReviewComment(),soon,expired);}
 public Map<String,Object> summary(){LocalDate t=LocalDate.now();return Map.of("total",repo.count(),"pending",repo.countByStatus("PENDING"),"verified",repo.countByStatus("VERIFIED"),"rejected",repo.countByStatus("REJECTED"),"expired",repo.countByExpiryDateBetween(LocalDate.of(2000,1,1),t.minusDays(1)),"expiringSoon",repo.countByExpiryDateBetween(t,t.plusDays(30)));}
}
